  // Scroll reveal
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(e => {
      if (e.isIntersecting) e.target.classList.add('visible');
    });
  }, { threshold: 0.1 });

  document.querySelectorAll('.reveal').forEach(el => observer.observe(el));

  // Typing effect on terminal (optional enhancement)
  const lines = document.querySelectorAll('.terminal-line');
  lines.forEach((line, i) => {
    line.style.opacity = '0';
    setTimeout(() => {
      line.style.transition = 'opacity 0.3s';
      line.style.opacity = '1';
    }, i * 500 + 1000);
  });

(function() {
  var WELCOME = "Hi! I'm virtual Iman, ask me anything!";
  var BOT_NAME = "Iman AI";
  var AVATAR = "data:image/png;base64,";


  var btn = document.createElement("div");
  btn.id = "imanai-btn";
  var bimg = document.createElement("img");
  bimg.id = "imanai-btn-img";
  bimg.src = AVATAR;
  bimg.alt = "Iman AI";
  var blabel = document.createElement("div");
  blabel.id = "imanai-btn-label";
  blabel.textContent = "Ask Iman AI";
  btn.appendChild(bimg);
  btn.appendChild(blabel);

  var box = document.createElement("div");
  box.id = "imanai-box";
  var hdr = document.createElement("div");
  hdr.id = "imanai-hdr";
  var himg = document.createElement("img");
  himg.src = AVATAR; himg.alt = "Iman AI";
  var htxt = document.createElement("div");
  var hname = document.createElement("div");
  hname.id = "imanai-hname"; hname.textContent = BOT_NAME;
  var hstatus = document.createElement("div");
  hstatus.id = "imanai-hstatus"; hstatus.textContent = "Online";
  htxt.appendChild(hname); htxt.appendChild(hstatus);
  var hclose = document.createElement("button");
  hclose.id = "imanai-close"; hclose.textContent = "x";
  hdr.appendChild(himg); hdr.appendChild(htxt); hdr.appendChild(hclose);

  var msgsDiv = document.createElement("div");
  msgsDiv.id = "imanai-msgs";

  var inpArea = document.createElement("div");
  inpArea.id = "imanai-inp-area";
  var inp = document.createElement("input");
  inp.id = "imanai-inp"; inp.type = "text"; inp.placeholder = "Tanya saya sesuatu...";
  var sendBtn = document.createElement("button");
  sendBtn.id = "imanai-send"; sendBtn.textContent = ">";
  inpArea.appendChild(inp); inpArea.appendChild(sendBtn);

  var tsDiv = document.createElement("div");
  tsDiv.id = "imanai-ts";
  box.appendChild(hdr); box.appendChild(msgsDiv); box.appendChild(tsDiv); box.appendChild(inpArea);
  document.body.appendChild(btn);
  document.body.appendChild(box);

  var isOpen = false;
  var tsToken = null;
  var tsWidgetId = null;

  function initTurnstile() {
    if (window.turnstile && !tsWidgetId) {
      tsWidgetId = window.turnstile.render(document.getElementById('imanai-ts'), {
        sitekey: '0x4AAAAAADMDRc1K7hI01J9r',
        theme: 'dark',
        size: 'invisible',
        callback: function(token) { tsToken = token; },
        'expired-callback': function() { tsToken = null; if (tsWidgetId) window.turnstile.reset(tsWidgetId); },
        'error-callback': function() { tsToken = null; }
      });
    }
  }

  function addMsg(text, sender) {
    var m = document.createElement("div");
    m.className = "imanai-m " + sender;
    m.textContent = text;
    msgsDiv.appendChild(m);
    msgsDiv.scrollTop = msgsDiv.scrollHeight;
  }

  function showTyping() {
    var t = document.createElement("div");
    t.className = "imanai-typing"; t.id = "imanai-t";
    for(var i=0;i<3;i++){var d=document.createElement("div");d.className="imanai-dot";t.appendChild(d);}
    msgsDiv.appendChild(t); msgsDiv.scrollTop = msgsDiv.scrollHeight;
  }

  function removeTyping() { var t=document.getElementById("imanai-t"); if(t) t.remove(); }

  function send(text) {
    if (!text.trim()) return;
    var token = tsToken;
    tsToken = null;
    addMsg(text, "user"); inp.value = ""; showTyping();
    fetch("/chat", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({message: text, ts_token: token || ''})
    }).then(function(res){ return res.json(); })
    .then(function(data){
      removeTyping();
      addMsg(data.reply || "Maaf, cuba lagi.", "bot");
      if (window.turnstile && tsWidgetId) window.turnstile.reset(tsWidgetId);
    })
    .catch(function(){ removeTyping(); addMsg("Maaf, ada masalah teknikal.", "bot"); });
  }

  btn.addEventListener("click", function() {
    isOpen = !isOpen;
    if (isOpen) {
      box.classList.add("open");
      if (!msgsDiv.children.length) addMsg(WELCOME, "bot");
      inp.focus();
      initTurnstile();
    } else { box.classList.remove("open"); }
  });

  hclose.addEventListener("click", function(){ isOpen=false; box.classList.remove("open"); });
  sendBtn.addEventListener("click", function(){ send(inp.value); });
  inp.addEventListener("keydown", function(e){ if(e.key==="Enter") send(inp.value); });
})();